import{_ as n,a0 as a,w as l,s as i,ao as S,I as p,x as e,a1 as r,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"ESI 集團同 ENSAM 合作，開源其 Inpsector 軟件 | LCTT x X-CMD","titleTemplate":false,"description":"ESI 集團同 ENSAM 合作，開源其 Inpsector 軟件 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"ESI 集團同 ENSAM 合作，開源其 Inpsector 軟件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"ESI 集團同 ENSAM 合作，開源其 Inpsector 軟件 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220504 ESI Group Collaborates With ENSAM, Open Sources Its “Inspector” Software","title":"ESI 集團同 ENSAM 合作，開源其 Inpsector 軟件","tag":"202205","desc":""},"relativePath":"202205/20220504 ESI Group Collaborates With ENSAM, Open Sources Its “Inspector” Software.md","filePath":"[post].md"}'),u={name:"202205/20220504 ESI Group Collaborates With ENSAM, Open Sources Its “Inspector” Software.md"};function I(f,t,E,m,d,w){const o=a("Link");return l(),i("div",null,[t[15]||(t[15]=S('<h1 id="esi-集團同-ensam-合作-開源其-inpsector-軟件" tabindex="-1">ESI 集團同 ENSAM 合作，開源其 Inpsector 軟件 <a class="header-anchor" href="#esi-集團同-ensam-合作-開源其-inpsector-軟件" aria-label="Permalink to “ESI 集團同 ENSAM 合作，開源其 Inpsector 軟件”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/05/software-696x371.jpg" alt="software"></p><p>Inspector 是一個可視化的交互式數據探索軟件，能夠對海量數據進行分析並提取相關信息，可用於預測性維修、網絡安全、控制、機器學習算法分析等。</p><p>通過讓更多的人使用 Inspector 軟件，讓他們能夠合作開發可靠靈活的方案，以解決社區的技術問題和特殊需求，ESI 集團增加了對工業界和學術界的貢獻。</p><p>作為 ESI 集團和 ENSAM 之間持續贊助合作和共創夥伴關係的一部分，將由 ENSAM（<ruby>巴黎高科國立高等工程技術大學<rt>Ecole Nationale Supérieure d’Arts et Métiers</rt></ruby>）領導 Inspector 的增長和擴展。通過共同參與建設由新加坡國家科學研究中（CNRS）協調的 Descartes 計劃、CREATE-ID 國際研究講座以及 ESI – ENSAM 虛擬工程實驗室，雙方加強了合作。</p><p>這種開源方式有許多好處。首先，社區能夠以最有效的方式使用該軟件，科學界能夠從根據用户需求定製的新功能以及安全方面的改進中受益。其次，ESI 集團希望提供一個從軟件中獲利機會，包括汽車及航空在內的各種行業的客户已經證明了這一軟件的可靠性。由於許多利益相關者的參與，Inspector 將持續發展以應對社區需求。</p><p>ESI 集團打算將其數據分析軟件開源發佈，得到了一些行業領導者和 Inspector 用户的興趣和支持，例如 CNS 就是其中一例。</p><p>CNS 的總經理 Stephane Perrin 表示：“ESI 集團這一決定證明了集團的先進技術對創新和科學生態系統的貢獻。CNS 作為一家網絡與安全的專業公司，我們用行動支持 Inspector 的未來。除了將 Inspector 集成到我們的持續網絡審計軟件套件中外，不久後我們還將通過我們創新解決方案的業務部門為該軟件提供支持。”</p><hr>',9)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),r(o,{href:"https://www.opensourceforu.com/2022/05/esi-group-collaborates-with-ensam-open-sources-its-inspector-software/"},{default:s(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/05/esi-group-collaborates-with-ensam-open-sources-its-inspector-software/",-1)])]),_:1})]),p("p",null,[t[6]||(t[6]=e("作者：",-1)),r(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:s(()=>[...t[2]||(t[2]=[e("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),r(o,{href:"https://github.com/lkxed"},{default:s(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),r(o,{href:"https://github.com/Veryzzj"},{default:s(()=>[...t[4]||(t[4]=[e("Veryzzj",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:s(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[12]||(t[12]=e("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:s(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const A=n(u,[["render",I]]);export{T as __pageData,A as default};
